package com.tradereview.app.v200
import org.junit.Test
import org.junit.Assert.*
import java.math.BigDecimal
import java.time.LocalDate
class ChartScaleTest {
    private fun d(v:String)=BigDecimal(v)
    @Test fun positiveNegativeAndMixedAxesContainRealValuesAndExactZero(){for(values in listOf(listOf(d("100")),listOf(d("-100")),listOf(d("-37.5"),d("123.45")))){val axis=ChartScale.axis(values);assertTrue(axis.minimum<=values.minOrNull()!!);assertTrue(axis.maximum>=values.maxOrNull()!!);assertTrue(axis.ticks.any{it.signum()==0});assertTrue(axis.ticks.zipWithNext().all{(a,b)->b-a==axis.step});assertTrue(axis.ticks.size<=12)}}
    @Test fun emptyAndFlatHaveUsableZeroAxisWithoutFabricatedSamples(){val axis=ChartScale.axis(emptyList());assertEquals(120f,ChartScale.y(BigDecimal.ZERO,axis,240f),.001f);assertEquals(axis,ChartScale.axis(listOf(BigDecimal.ZERO)))}
    @Test fun projectionNeverReversesProfitAndLoss(){val axis=ChartScale.axis(listOf(d("-100"),d("100")));assertTrue(ChartScale.y(d("100"),axis,240f)<ChartScale.y(BigDecimal.ZERO,axis,240f));assertTrue(ChartScale.y(d("-100"),axis,240f)>ChartScale.y(BigDecimal.ZERO,axis,240f));assertTrue(ChartScale.x(d("-100"),axis,320f)<ChartScale.x(BigDecimal.ZERO,axis,320f))}
    @Test fun touchBoundariesAndScrolledLocalCoordinatesAreDeterministic(){assertEquals(0,ChartScale.hitIndex(0f,52f,31));assertEquals(1,ChartScale.hitIndex(52f,52f,31));assertEquals(30,ChartScale.hitIndex(1611f,52f,31));assertNull(ChartScale.hitIndex(1612f,52f,31));assertNull(ChartScale.hitIndex(-1f,52f,31));assertNull(ChartScale.hitIndex(Float.NaN,52f,31));assertEquals(8,ChartScale.hitIndex(10f+52f*8,52f,31))}
    @Test fun moneyUnitsAndTinyDecimalsKeepExactTickAmounts(){val large=ChartScale.axis(listOf(d("123450000")));assertEquals("亿元",large.unitLabel);assertEquals("1.50",large.label(d("150000000")));val small=ChartScale.axis(listOf(d("0.0000123")));assertTrue(small.maximum>=d("0.0000123"));assertTrue(small.step>BigDecimal.ZERO)}
    @Test fun weekStartsOnMondayAcrossYearBoundary(){val p=LedgerPeriod.week(LocalDate.of(2025,1,1));assertEquals(LocalDate.of(2024,12,30).toEpochDay(),p.start);assertEquals(LocalDate.of(2025,1,5).toEpochDay(),p.end)}
    @Test fun monthsHaveTwentyEightTwentyNineThirtyAndThirtyOneCorrectDays(){for((date,size) in listOf(LocalDate.of(2025,2,1) to 28,LocalDate.of(2024,2,1) to 29,LocalDate.of(2025,4,1) to 30,LocalDate.of(2025,1,1) to 31))assertEquals(size,LedgerPeriod.month(date).days.size)}
    @Test fun previousMonthAndYearAreCorrect(){assertEquals(LocalDate.of(2024,12,1).toEpochDay(),LedgerPeriod.month(LocalDate.of(2025,1,15),-1).start)}
    private fun event(id:String,market:String,day:Long,net:String)=ClosedEvent(LedgerExecution(id,market,if(market=="stock")"600000"else"rb2701","合成",day,600,day,0,"sell","close","10","1","0"),d(net))
    @Test fun onlyCloseEventsInPeriodAndSelectedMarketContribute(){val day=LocalDate.of(2025,1,2).toEpochDay();val data=listOf(event("a","stock",day,"100.1"),event("b","futures",day,"-25.35"),event("c","stock",day+7,"999"));val p=LedgerPeriod.week(LocalDate.ofEpochDay(day));val all=periodNumbers(data,p);assertEquals(2,all.records.size);assertEquals(d("74.75"),all.net);assertEquals(d("100.1"),periodNumbers(data,p,"stock").net);assertEquals(d("-25.35"),periodNumbers(data,p,"futures").net)}
    @Test fun flatTradeAndMissingDayAreDistinctAndEmptyAverageIsNull(){val day=LocalDate.of(2025,1,2).toEpochDay();val p=LedgerPeriod.week(LocalDate.ofEpochDay(day));val n=periodNumbers(listOf(event("a","stock",day,"0")),p);assertEquals(1,n.flats);assertTrue(n.daily.containsKey(day));assertFalse(n.daily.containsKey(day+1));assertNull(periodNumbers(emptyList(),p).average);assertNull(periodNumbers(emptyList(),p).winRate)}
    @Test fun monthlyContractDistributionSumsActualSignedResults(){val day=LocalDate.of(2025,1,2).toEpochDay();val n=periodNumbers(listOf(event("a","stock",day,"100"),event("b","stock",day+1,"-20"),event("c","futures",day,"-50")),LedgerPeriod.month(LocalDate.ofEpochDay(day)));assertEquals(2,n.distribution.size);assertEquals(d("80"),n.distribution.first{it.first.endsWith("600000")}.second);assertEquals(d("-50"),n.distribution.first{it.first.endsWith("rb2701")}.second)}
}
